# gucci gang
dfs = function(remain, temp_str, lst){
    if (remain == 0){
        lst &lt;- append(lst, list(temp_str))
        return(lst)
    }

    if (remain &gt;= 1) {
        next_str &lt;- if (temp_str == "") "gang" else
            paste(temp_str, "gang", sep = "")
        lst &lt;- dfs(remain - 1, next_str, lst);
    }

    if (remain &gt;= 2) {
        next_str &lt;- if (temp_str == "") "gucci" else
            paste(temp_str, "gucci", sep = "");
        lst &lt;- dfs(remain - 2, next_str, lst)
    }

    lst
}

gucci.gang = function(x){
    if (mode(x) != 'numeric') {
        print("error");
        return(NULL);
    }

    lst &lt;- list();
    y &lt;- '';
    lst &lt;- dfs(x, y, lst);
    lst &lt;- as.character(lst);
    lst
}

gucci.gang(3)

